/**
 * A converted world folder, served to the shell from memory.
 *
 * The shell loads a world by address and fetches what its document names,
 * and only http and https addresses count as resources (VEML §1.4), so the
 * folder is given addresses on the page's own origin: each file is stored
 * under `<scope>__import/<id>/<path>` where the import service worker
 * (`public/import-sw.js`) answers for it. The document is not rewritten:
 * its relative references resolve under the same prefix, exactly as on a
 * host. Nothing else about the load changes, which is the point.
 */

export interface WorldFile {
  path: string;
  bytes: Uint8Array;
}

/** Where the files are kept for the worker to answer from; the Cache API in a browser, a map in a test. */
export interface FileStore {
  put(url: string, bytes: Uint8Array, contentType: string): Promise<void>;
  delete(url: string): Promise<void>;
  /** Forgets everything staged, this session's and any earlier one's: the store outlives the page. */
  clear?(): Promise<void>;
}

export interface StagedWorld {
  /** The document's address, to load as any world. */
  documentUrl: string;
  /** Every address staged, the document's among them. */
  urls: readonly string[];
  /** Removes the files from the store; call once the world is unloaded. */
  release(): Promise<void>;
}

export const WORLD_DOCUMENT = 'index.veml';
export const IMPORT_PREFIX = '__import/';

const MIME: Record<string, string> = {
  '.veml': 'application/xml',
  '.glb': 'model/gltf-binary',
  '.png': 'image/png',
  '.jpg': 'image/jpeg',
  '.jpeg': 'image/jpeg',
  '.webp': 'image/webp',
  '.ktx2': 'image/ktx2',
  '.json': 'application/json',
  '.js': 'text/javascript',
  '.mp3': 'audio/mpeg',
  '.ogg': 'audio/ogg',
  '.wav': 'audio/wav',
};

export const contentTypeOf = (path: string): string => {
  const dot = path.lastIndexOf('.');
  return (dot < 0 ? undefined : MIME[path.slice(dot).toLowerCase()]) ?? 'application/octet-stream';
};

/**
 * Stages the folder under `scopeUrl` (the worker's scope, a directory URL
 * ending in `/`) with a fresh id, so two imports never share an address and a
 * cached asset of one is never served for the other.
 */
export async function stageWorldFiles(files: readonly WorldFile[], store: FileStore, scopeUrl: string, id: string = freshId()): Promise<StagedWorld> {
  if (!files.some((f) => f.path === WORLD_DOCUMENT)) throw new Error(`the world folder has no ${WORLD_DOCUMENT}`);
  const base = new URL(`${IMPORT_PREFIX}${id}/`, scopeUrl).href;
  const urls: string[] = [];
  for (const f of files) {
    const url = new URL(f.path, base).href;
    await store.put(url, f.bytes, contentTypeOf(f.path));
    urls.push(url);
  }
  return {
    documentUrl: new URL(WORLD_DOCUMENT, base).href,
    urls,
    release: async () => {
      for (const u of urls) await store.delete(u);
    },
  };
}

function freshId(): string {
  const c = globalThis.crypto;
  if (c?.randomUUID) return c.randomUUID().slice(0, 8);
  return Math.random().toString(36).slice(2, 10);
}
